def 고침(p, edits):
    raw = p.read_bytes().decode("utf-8")
    pass  # 문서단계_목록은 LF
    s = raw.replace("\r\n", "\n")
    for old, new in edits:
        assert s.count(old) == 1, (p.name, s.count(old), old[:70])
        s = s.replace(old, new)
    return s


